-- Task 18: large models. A service past writer.SINGLE_FILE_MAX_* is split into
-- service.lua + service/{shapes,ops,errors}_NNN.lua; shapes load on first use. The limits
-- are lowered here so a small synthetic model (verify/lib/big_synth.lua) splits, which
-- keeps the spec fast under gopher-lua. The generated files are loaded from memory
-- through package.preload, under a module name of the spec's choosing (as a vendored
-- client would be).
local t = require("spec.harness")
local gen = require("distilled.gen")
local writer = require("distilled.gen.writer")
local emit = require("distilled.gen.emit")
local compat = require("distilled.compat")
local testing = require("distilled.testing")
local synth = require("verify.lib.big_synth")

local LIMITS = {
  "SINGLE_FILE_MAX_BYTES",
  "SINGLE_FILE_MAX_CONSTANTS",
  "CHUNK_BYTES",
  "CHUNK_CONSTANTS",
  "MAX_CONSTANTS",
  "MAX_DEPTH",
}

-- with_limits(overrides, fn): fn() with writer limits changed, restored even on failure
local function with_limits(overrides, fn)
  local saved = {}
  for _, k in ipairs(LIMITS) do
    saved[k] = writer[k]
  end
  for k, v in pairs(overrides) do
    writer[k] = v
  end
  local ok, a, b, c = t.pcall(fn)
  for _, k in ipairs(LIMITS) do
    writer[k] = saved[k]
  end
  if not ok then
    error(a, 0)
  end
  return a, b, c
end

local SMALL = { SINGLE_FILE_MAX_BYTES = 4000, CHUNK_BYTES = 6000 }

local function generate(opts, limits, args)
  local m = assert(gen.model.from_text(synth.text(opts)))
  return with_limits(limits or SMALL, function()
    local a = { model = m, provider = synth.provider() }
    for k, v in pairs(args or {}) do
      a[k] = v
    end
    return gen.generate(a)
  end)
end

-- install(files, prefix) -> loads (list of required modules), uninstall()
local function install(files, prefix)
  local loads, names = {}, {}
  for _, path in ipairs(files.order) do
    local stem = string.match(path, "^(.*)%.lua$")
    if stem and path ~= "types.lua" then
      local module = prefix
      if stem ~= "init" then
        module = prefix .. "." .. string.gsub(stem, "/", ".")
      end
      names[#names + 1] = module
      package.loaded[module] = nil
      package.preload[module] = function()
        loads[#loads + 1] = module
        return assert(compat.load(files[path], "=" .. module))(module)
      end
    end
  end
  return loads,
    function()
      for _, module in ipairs(names) do
        package.preload[module] = nil
        package.loaded[module] = nil
      end
    end
end

-- an assertion that failed inside t.pcall, raised again after the cleanup
local function rethrow(ok, err)
  if not ok then
    error(err, 0)
  end
end

local function count(list, pattern)
  local n = 0
  for _, s in ipairs(list) do
    if string.find(s, pattern) then
      n = n + 1
    end
  end
  return n
end

t.describe("gen: large models are split (task 18)", function()
  t.it("keeps a model under the limits in one service.lua", function()
    local files, err = generate({ ops = 2 }, {})
    t.truthy(files, err)
    t.same(files.order, { "README.md", "init.lua", "service.lua", "types.lua" })
    t.same(files.dirs, {})
    t.no_match(files["service.lua"], "shape_chunks", true)
  end)

  t.it("splits a big one into shape, op and error files under service/", function()
    local files, err = generate({ ops = 12, members = 6 })
    t.truthy(files, err)
    t.same(files.dirs, { "service" })
    t.truthy(files["service/shapes_001.lua"])
    t.truthy(files["service/ops_001.lua"])
    t.truthy(count(files.order, "^service/shapes_") > 1, "several shape files")
    t.eq(count(files.order, "^service/errors_"), 0, "small errors stay in service.lua")
    t.match(files["service.lua"], "classes.NotFound = errors.define", true)
    for _, path in ipairs(files.order) do
      if string.find(path, "^service/") then
        t.truthy(#files[path] <= 6000 + 2000, path .. " is about CHUNK_BYTES")
        t.match(files[path], "Generated by distilled-lua", true)
        t.truthy(compat.load(files[path], "=" .. path), path .. " compiles")
      end
    end
    t.truthy(compat.load(files["service.lua"], "=service.lua"))
    -- every shape is in the index once, with its file
    local listed = 0
    for file, name in string.gmatch(files["service.lua"], "\n(%d%d%d) ([^\n]+)") do
      listed = listed + 1
      t.match(files["service/shapes_" .. file .. ".lua"], "\nshapes." .. name .. " =", true)
    end
    t.eq(listed, 12 * 4 + 1, "4 shapes per operation and the shared enum")
  end)

  t.it("is deterministic", function()
    local a = generate({ ops = 12, members = 6 })
    local b = generate({ ops = 12, members = 6 })
    t.same(a.order, b.order)
    for _, path in ipairs(a.order) do
      t.eq(a[path], b[path], path)
    end
  end)

  t.it("puts an operation's shapes together, wherever their names sort", function()
    -- Op1, Op10, Op11, Op12, Op2, ... sort apart from the method order op1, op2, ...
    local files = generate({ ops = 12, members = 6 })
    local where = {}
    for file, name in string.gmatch(files["service.lua"], "\n(%d+) ([^\n]+)") do
      where[name] = file
    end
    local together = 0
    for i = 1, 12 do
      local p = "Op" .. i
      if
        where[p .. "Request"] == where[p .. "ItemList"]
        and where[p .. "ItemList"] == where[p .. "Item"]
      then
        together = together + 1
      end
    end
    t.truthy(
      together >= 10,
      together .. " of 12 operations have request, list and item in one file"
    )
  end)

  t.it("loads lazily: require reads no shape file, a lookup reads one", function()
    local files = generate({ ops = 12, members = 6 })
    local loads, uninstall = install(files, "vendored.syn")
    local ok, err = t.pcall(function()
      local service = require("vendored.syn.service")
      t.eq(count(loads, "%.shapes_"), 0, "no shape file loaded by require")
      t.truthy(count(loads, "%.ops_") >= 1, "every op file loaded")
      local n = 0
      for _ in pairs(service.ops) do
        n = n + 1
      end
      t.eq(n, 12, "service.ops is complete")
      t.truthy(#service.shape_chunks > 1)
      t.eq(service.shape_chunks[1], "vendored.syn.service.shapes_001")
      t.eq(service.shapes["NoSuchShape"], nil)
      t.eq(count(loads, "%.shapes_"), 0, "an unknown name loads nothing")
      local node = service.shapes.Op3Request
      t.eq(node.t, "struct")
      t.eq(count(loads, "%.shapes_"), 1, "one file for Op3Request")
      t.eq(service.shapes.Op3Request, node, "the same node again")
      local _ = service.shapes.Op3Item
      t.eq(count(loads, "%.shapes_"), 1, "Op3Item is in the same file")
      -- every file: its shapes resolve through the registry to the same nodes
      for _, m in ipairs(service.shape_chunks) do
        for name, shape in pairs(require(m)) do
          t.eq(service.shapes[name], shape, name)
        end
      end
    end)
    uninstall()
    rethrow(ok, err)
  end)

  t.it("calls operations through the split client, success and error", function()
    local files = generate({ ops = 12, members = 6 })
    local _, uninstall = install(files, "syn")
    local ok, err = t.pcall(function()
      local Syn = require("syn")
      local host = testing.host({
        responses = {
          { status = 200, body = { thing = { field1 = "a" }, kind = "v2" } },
          { status = 404, body = { message = "gone" } },
          { status = 200, body = { thing = { field2 = "no field1" } } },
        },
      })
      local client = Syn.new({ host = host, api_key = "k", retry = "none" })
      local out, cerr = client:op7({ id = "x", field1 = "f", items = { { field1 = "i" } } })
      t.truthy(out, cerr and (tostring(cerr.tag) .. ": " .. tostring(cerr.message)))
      t.eq(out.thing.field1, "a")
      t.eq(host.requests[1].url, "https://syn.example.test/things7/x")
      t.match(host.requests[1].body, '"items":[{"field1":"i"}]', true)
      local none, e = client:op8({ id = "y", field1 = "f" })
      t.eq(none, nil)
      t.eq(e.tag, "NotFound")
      t.eq(e.message, "gone")
      -- strict validation walks the output shapes through the lazy registry too
      local strict = client:with({ validation = "strict" })
      local bad, verr = strict:op9({ id = "z", field1 = "f" })
      t.eq(bad, nil)
      t.eq(verr.tag, "SynParseError")
      t.match(tostring(verr.cause and verr.cause.message), "field1", true)
    end)
    uninstall()
    rethrow(ok, err)
  end)

  t.it("a missing shape file raises on lookup, naming the module", function()
    local files = generate({ ops = 12, members = 6 })
    files["service/shapes_002.lua"] = nil
    for i, path in ipairs(files.order) do
      if path == "service/shapes_002.lua" then
        table.remove(files.order, i)
        break
      end
    end
    local _, uninstall = install(files, "broken.syn")
    local ok, err = t.pcall(function()
      local service = require("broken.syn.service")
      local in_two
      for file, name in string.gmatch(files["service.lua"], "\n(%d+) ([^\n]+)") do
        if file == "002" then
          in_two = name
        end
      end
      t.raises(function()
        return service.shapes[in_two]
      end, "broken.syn.service.shapes_002")
    end)
    uninstall()
    rethrow(ok, err)
  end)

  t.it("splits big error sets into errors files", function()
    local files, err = generate({ ops = 12, members = 6 }, {
      SINGLE_FILE_MAX_BYTES = 4000,
      CHUNK_BYTES = 100,
    })
    t.truthy(files, err)
    t.truthy(files["service/errors_001.lua"])
    t.no_match(files["service.lua"], "errors.define", true)
    local _, uninstall = install(files, "errs.syn")
    local ok, lerr = t.pcall(function()
      local service = require("errs.syn.service")
      t.truthy(service.errors.NotFound)
      t.eq(service.errors.NotFound.tag, "NotFound")
    end)
    uninstall()
    rethrow(ok, lerr)
  end)

  t.it("splits on the constant count too", function()
    local files = generate({ ops = 3 }, { SINGLE_FILE_MAX_CONSTANTS = 50 })
    t.truthy(files["service/shapes_001.lua"], "split by constants alone")
  end)

  t.it("--ops of a big model can fit one file again", function()
    local files, err = generate({ ops = 12, members = 6 }, SMALL, { ops = { "op1" } })
    t.truthy(files, err)
    t.same(files.dirs, {})
  end)

  t.it("fails early on a statement past one function's limits", function()
    local files, err = generate({ ops = 2, enum_values = 50 }, { MAX_CONSTANTS = 40 })
    t.eq(files, nil)
    t.match(err, "shape syn.api#Kind needs about %d+ Lua constants")
    t.match(err, "MAX_CONSTANTS 40", true)
    files, err = generate({ ops = 2 }, { MAX_DEPTH = 2 })
    t.eq(files, nil)
    t.match(err, "tables deep, past what the Lua parsers accept", true)
  end)

  t.it("README, init.lua and types.lua do not change with the layout", function()
    local split = generate({ ops = 12, members = 6 })
    local single = generate({ ops = 12, members = 6 }, {})
    for _, path in ipairs({ "README.md", "init.lua", "types.lua" }) do
      t.eq(split[path], single[path], path)
    end
  end)
end)

t.describe("gen.emit: long strings and scan (task 18)", function()
  t.it("long_string picks a level its content cannot close", function()
    for _, s in ipairs({ "a\n", "x]]y\n", "]=]]==]\n", "ends]" }) do
      local code = "return " .. emit.long_string(s)
      t.eq(assert(compat.load(code, "=ls"))(), s, s)
    end
  end)

  t.it("scan counts literals, tables, depth and refs in emission order", function()
    local v = {
      t = "struct",
      members = emit.list({
        { name = "a", schema = emit.call("S.ref", "A") },
        { name = "b", schema = emit.call("S.nullable", emit.call("S.ref", "B")) },
        { name = "c", schema = emit.raw("S.string"), n = 2 },
      }),
    }
    local f = emit.scan(v)
    t.same(f.refs, { "A", "B" })
    t.truthy(f.strings["struct"] and f.strings["a"] and f.strings["S.string"])
    t.truthy(f.numbers[2])
    t.eq(f.raw["S.string"], true)
    t.eq(f.depth, 5, "record > list > member > S.nullable > S.ref")
    t.eq(f.tables, 8)
  end)
end)

t.describe("bin/distilled-lua with a large model (task 18)", function()
  if rawget(_G, "rex") then
    t.pending("CLI: needs io.popen (lua and luajit only)")
    return
  end
  local function run(cmd)
    local p = io.popen(cmd .. ' 2>&1; echo "exit:$?"')
    local out = p:read("*a")
    p:close()
    local code = tonumber(string.match(out, "exit:(%d+)%s*$"))
    return (string.gsub(out, "exit:%d+%s*$", "")), code
  end
  local function write(path, text)
    local f = assert(io.open(path, "wb"))
    f:write(text)
    f:close()
  end
  local function exists(path)
    local f = io.open(path, "rb")
    if f then
      f:close()
    end
    return f ~= nil
  end
  local lua = rawget(_G, "jit") and "luajit" or "lua"
  local bin = lua .. " " .. t.root .. "/bin/distilled-lua"
  local SPEC = [[
return {
  name = "syn",
  base_url = "https://syn.example.test",
  auth = { kind = "bearer", from = "api_key", env = "SYN_API_KEY" },
  unknown_tag = "UnknownSynError",
  parse_tag = "SynParseError",
  naming = { members = "wire" },
}
]]

  t.it(
    "package: a split model next to a small one, the index, gen-check; generate cleans up",
    function()
      local dir = os.tmpname()
      os.remove(dir)
      run("mkdir -p " .. dir .. "/models/syn")
      -- 600 operations: past SINGLE_FILE_MAX_BYTES with the real limits
      write(dir .. "/models/syn/big.json", synth.text({ ops = 600, members = 8 }))
      write(dir .. "/models/syn/small.json", synth.text({ ops = 3 }))
      write(dir .. "/syn.lua", SPEC)
      local out, code = run(
        bin
          .. " package --models "
          .. dir
          .. "/models/syn --provider "
          .. dir
          .. "/syn.lua --out "
          .. dir
          .. "/clients/syn"
      )
      t.eq(code, 0, out)
      t.match(out, "ok   syn/big: 600 operations", true)
      t.truthy(exists(dir .. "/clients/syn/big/service/shapes_001.lua"), "big is split")
      t.truthy(exists(dir .. "/clients/syn/big/service/ops_001.lua"))
      t.falsy(exists(dir .. "/clients/syn/small/service"), "small is one file")
      out, code = run(
        lua
          .. " "
          .. t.root
          .. "/verify/lib/gen_check.lua "
          .. t.root
          .. " "
          .. dir
          .. "/clients syn"
      )
      t.eq(code, 0, out)
      t.match(out, "ok gen-check", true)
      t.match(out, "2 services", true)
      t.match(out, "603/603 ops built", true)

      -- generate into an existing split client: stale chunk files go; --ops fits one file
      local client = dir .. "/clients/syn/big"
      write(client .. "/service/shapes_999.lua", "return {}")
      out, code = run(
        bin
          .. " generate --model "
          .. dir
          .. "/models/syn/big.json --provider "
          .. dir
          .. "/syn.lua --model-name big --out "
          .. client
      )
      t.eq(code, 0, out)
      t.falsy(exists(client .. "/service/shapes_999.lua"), "stale file removed")
      t.truthy(exists(client .. "/service/shapes_001.lua"))
      out, code = run(
        bin
          .. " generate --model "
          .. dir
          .. "/models/syn/big.json --provider "
          .. dir
          .. "/syn.lua --model-name big --ops op1,op2 --out "
          .. client
      )
      t.eq(code, 0, out)
      t.falsy(exists(client .. "/service/shapes_001.lua"), "one file again")
      run("rm -rf " .. dir)
    end
  )
end)
